def max_product_no_common_bits(nums):
    B = max(nums).bit_length()
    size = 1 << B
    full = size - 1
    # best[mask] = largest element of nums that is a submask of mask
    best = [0] * size
    for x in nums:
        if x > best[x]:
            best[x] = x
    for b in range(B):
        bit = 1 << b
        for base in range(0, size, bit << 1):
            for mask in range(base + bit, base + (bit << 1)):
                v = best[mask ^ bit]
                if v > best[mask]:
                    best[mask] = v
    ans = 0
    for x in nums:
        y = best[full ^ x]
        if y and x * y > ans:
            ans = x * y
    return ans
